te === "trying"} locale={settings.locale} onClick={state === "success" ? () => { setState("wait"); setCountdown(5); setAttempts(1); } : retry}>{state === "success" ? (en ? "Replay error" : "重新演示") : (en ? "Retry now" : "立即重试")}</Button></div></SurfaceCard></ActionStage>;
