    const tick = (now: number) => { setLevel(reduced ? .4 : Math.abs(Math.sin(now / 140) * .6 + Math.sin(now / 77) * .25)); if (!reduced) frame = requestAnimationFrame(tick); };
    frame = requestAnimationFrame(tick);
