"use client";

import { useRef, useState } from "react";
import { AnimatePresence, motion as m, useReducedMotion } from "motion/react";
import { Button, CheckboxWithLabel, FilterPanel, ListGroup, ListItem, SurfaceCard, TextField } from "@forge-ui-official/core";
import { CloseCircleLinear, DocumentTextLinear, MagniferLinear } from "@forge-ui-official/core/icons";
import type { FusionExampleProps, FusionSettings } from "./types";

type Result = { id: string; zh: string; en: string; red?: boolean; size?: boolean; cheap?: boolean; pdf?: boolean; recent?: boolean; team?: boolean };
const products: Result[] = [
  { id: "daily", zh: "日常跑鞋", en: "Daily Runner", red: true, size: false, cheap: true },
  { id: "cushion", zh: "缓震跑鞋", en: "Cushion Runner", red: true, size: true, cheap: false },
  { id: "lite", zh: "轻量跑鞋", en: "Lite Runner", red: false, size: true, cheap: true },
  { id: "road", zh: "公路跑鞋", en: "Road Runner", red: false, size: true, cheap: true },
  { id: "slip", zh: "轻便运动鞋", en: "Slip-on Sneakers", red: true, size: true, cheap: true },
];
const documents: Result[] = [
  { id: "guide", zh: "设计规范", en: "Design guidelines", pdf: true, recent: true, team: false },
  { id: "review", zh: "设计评审记录", en: "Design review", pdf: false, recent: true, team: true },
  { id: "archive", zh: "设计归档", en: "Design archive", pdf: true, recent: false, team: true },
  { id: "engineering", zh: "工程规范", en: "Engineering guidelines", pdf: true, recent: true, team: true },
];
const normalize = (value: string) => value.toLocaleLowerCase().replace(/\s+/g, "");

export function SearchRecoveryExample({ id, locale, color, motion }: FusionExampleProps) {
  const zh = locale === "zh";
  const isProducts = id === "092";
  const data = isProducts ? products : documents;
  const filters: Array<{ key: keyof Result; label: string }> = isProducts
    ? [{ key: "red", label: zh ? "红色" : "Red" }, { key: "size", label: zh ? "尺码 270" : "Size 270" }, { key: "cheap", label: zh ? "优惠款" : "Budget" }]
    : [{ key: "pdf", label: "PDF" }, { key: "recent", label: zh ? "最近更新" : "Recent" }, { key: "team", label: zh ? "工程团队" : "Engineering" }];
  const [query, setQuery] = useState(isProducts ? (zh ? "跑协" : "runer") : (zh ? "设记" : "desgin"));
  const [active, setActive] = useState(filters.map(filter => filter.key));
  const [draft, setDraft] = useState(active);
  const [open, setOpen] = useState(false);
  const input = useRef<HTMLInputElement>(null);
  const reduced = useReducedMotion();
  const search = (searchQuery: string, keys: Array<keyof Result>) => data.filter(item => normalize(zh ? item.zh : item.en).includes(normalize(searchQuery)) && keys.every(key => item[key] === true));
  const result = search(query, active);
  const corrected = isProducts ? query.replace(/runer/gi, "runner").replace(/跑协/g, "跑鞋") : query.replace(/desgin/gi, "design").replace(/设记/g, "设计");
  function remove(key: keyof Result) { setActive(current => current.filter(item => item !== key)); input.current?.focus(); }
  function reset() { setActive([]); setQuery(""); input.current?.focus(); }
  return <div className="flex w-full flex-col gap-4">
    <TextField ref={input} label={zh ? (isProducts ? "搜索商品" : "搜索文档") : (isProducts ? "Search products" : "Search documents")} value={query} onChange={setQuery} color={color} iconLeft={<MagniferLinear size={18} />} />
    <div className="flex flex-wrap gap-2">
      {filters.filter(filter => active.includes(filter.key)).map(filter => <Button motion={motion} key={filter.key} size="sm" color={color} variant="secondary" iconRight={<CloseCircleLinear size={14} />} aria-label={`${zh ? "移除" : "Remove"} ${filter.label}`} onClick={() => remove(filter.key)}>{filter.label}</Button>)}
      <Button motion={motion} size="sm" color="black" variant="tertiary" aria-expanded={open} onClick={() => { setDraft(active); setOpen(!open); }}>{zh ? "筛选条件" : "Filters"}</Button>
    </div>
    {open && <FilterPanel color={color} title={zh ? "筛选" : "Filters"} resetLabel={zh ? "重置" : "Reset"} applyLabel={zh ? "应用" : "Apply"} cancelLabel={zh ? "取消" : "Cancel"} onReset={() => setDraft([])} onCancel={() => setOpen(false)} onApply={() => { setActive(draft); setOpen(false); }}>{filters.map(filter => <CheckboxWithLabel key={filter.key} label={filter.label} checked={draft.includes(filter.key)} color={color} onChange={checked => setDraft(current => checked ? [...current, filter.key] : current.filter(item => item !== filter.key))} />)}</FilterPanel>}
    <p role="status" className="text-sm text-fg-grey-700">{result.length} {zh ? "条结果" : "results"}</p>
    {result.length ? <ListGroup title={zh ? "搜索结果" : "Search results"} color={color} className="w-full" items={<div className="flex flex-col gap-4 p-4"><AnimatePresence initial={false}>{result.map(item => <m.div layout key={item.id} initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={{ duration: reduced || motion === "none" ? 0 : .2 }}><ListItem title={zh ? item.zh : item.en} subtitle={isProducts ? (zh ? "匹配当前条件" : "Matches current filters") : item.pdf ? "PDF" : "Markdown"} lead={{ kind: "icon", icon: <DocumentTextLinear size={18} />, color }} /></m.div>)}</AnimatePresence></div>} /> : <SurfaceCard title={zh ? "没有找到匹配结果" : "No matching results"}>
      <div className="flex flex-col items-start gap-3">
        <p className="text-sm text-fg-grey-700">{zh ? "调整搜索词或移除部分条件，找回相关内容。" : "Try a corrected query or remove a filter to recover results."}</p>
        {corrected !== query && <Button motion={motion} size="sm" color={color} variant="secondary" onClick={() => { setQuery(corrected); input.current?.focus(); }}>{zh ? `改为搜索“${corrected}”` : `Search for “${corrected}”`}</Button>}
        {active.map(key => {
          const count = search(query, active.filter(item => item !== key)).length;
          return count ? <Button motion={motion} key={key} size="sm" color={color} variant="tertiary" onClick={() => remove(key)}>{zh ? `移除“${filters.find(filter => filter.key === key)?.label}”，恢复 ${count} 条` : `Remove ${filters.find(filter => filter.key === key)?.label}: ${count} results`}</Button> : null;
        })}
        <Button motion={motion} size="sm" color="black" variant="tertiary" onClick={reset}>{zh ? "清空搜索和筛选" : "Clear search and filters"}</Button>
      </div>
    </SurfaceCard>}
  </div>;
}

export function GeneratedReviewExample({ locale, color, motion }: FusionSettings) {
  const zh = locale === "zh";
  const [decisions, setDecisions] = useState<Array<"pending" | "accept" | "keep">>(["pending", "pending"]);
  const reduced = useReducedMotion();
  const changes = zh ? [
    { name: "交互说明.md", before: "点击发送后清空所有内容。", after: "发送成功后清空草稿，失败时保留。" },
    { name: "组件规范.md", before: "智能体使用通用图标。", after: "智能体显示头像与名字。" },
  ] : [
    { name: "interaction.md", before: "Clear all content when Send is clicked.", after: "Clear the draft after sending succeeds; keep it on failure." },
    { name: "components.md", before: "Use a generic icon for agents.", after: "Display each agent's avatar and name." },
  ];
  function decide(index: number, next: "pending" | "accept" | "keep") { setDecisions(current => current.map((value, i) => i === index ? next : value)); }
  return <div className="flex w-full flex-col gap-4">
    {changes.map((change, index) => <SurfaceCard key={change.name} title={change.name} action={<span className="text-xs text-fg-grey-700">{decisions[index] === "pending" ? (zh ? "待审核" : "Pending") : decisions[index] === "accept" ? (zh ? "已接受" : "Accepted") : (zh ? "保留原文" : "Original retained")}</span>}>
      <div className="flex flex-col gap-3"><AnimatePresence initial={false}>
        {decisions[index] !== "accept" && <m.div key="before" initial={false} exit={{ opacity: 0, height: 0, x: reduced || motion === "none" ? 0 : -12 }} transition={{ duration: reduced || motion === "none" ? 0 : .2 }} className="overflow-hidden rounded-lg bg-fg-red-50 p-3 text-sm leading-6 text-fg-red"><span aria-hidden>− </span>{change.before}</m.div>}
        {decisions[index] !== "keep" && <m.div key="after" initial={false} exit={{ opacity: 0, height: 0, x: reduced || motion === "none" ? 0 : 12 }} transition={{ duration: reduced || motion === "none" ? 0 : .2 }} className="overflow-hidden rounded-lg bg-fg-green-50 p-3 text-sm leading-6 text-fg-green-700"><span aria-hidden>+ </span>{change.after}</m.div>}
      </AnimatePresence>
      <div className="flex flex-wrap gap-2">{decisions[index] === "pending" ? <><Button motion={motion} size="sm" color={color} onClick={() => decide(index, "accept")}>{zh ? "接受变更" : "Accept"}</Button><Button motion={motion} size="sm" variant="tertiary" color="black" onClick={() => decide(index, "keep")}>{zh ? "保留原文" : "Keep original"}</Button></> : <Button motion={motion} size="sm" color={color} variant="tertiary" onClick={() => decide(index, "pending")}>{zh ? "撤销决定" : "Undo decision"}</Button>}</div></div>
    </SurfaceCard>)}
    <p role="status" className="text-xs text-fg-grey-700">{decisions.filter(item => item !== "pending").length} / {changes.length} {zh ? "项已审核" : "reviewed"}</p>
  </div>;
}

src/app/components/_fusion/composition-w:
"use client";

import { useEffect, useState } from "react";
import { AnimatePresence, motion as m, useReducedMotion } from "motion/react";
import { AddMember, Avatar, AvatarGroup, Datepicker, Button, ButtonGroup, Checkbox, DataTable, EventCard, EventTag, IconButton, ProgressBar, ReviewItem, SurfaceCard, type ColumnDef } from "@forge-ui-official/core";
import { AltArrowLeftLinear, AltArrowRightLinear, CheckCircleLinear, CloseCircleLinear, CalendarLinear } from "@forge-ui-official/core/icons";
import type { FusionSettings } from "./types";

const portraits = ["/images/protask/crm/john-hoegan-avatar.png", "/images/protask/crm/linda-blair-avatar.png", "/images/protask/crm/team-avatar.png"];
const accent = (color: FusionSettings["color"]) => color === "purple" ? "var(--fg-violet)" : color === "blue" ? "var(--fg-blue)" : "var(--fg-black)";

export function ReviewCarouselExample({ locale, color, motion }: FusionSettings) {
  const zh = locale === "zh";
  const [index, setIndex] = useState(0);
  const [auto, setAuto] = useState(true);
  const [hover, setHover] = useState(false);
  const [focused, setFocused] = useState(false);
  const reduced = useReducedMotion();
  const names = zh ? ["林晓", "陈凡", "周宁"] : ["Alex Lin", "Chris Chen", "Jamie Zhou"];
  const quotes = zh ? ["组件和设计稿保持一致，交付周期缩短了一半。", "动效自然克制，放进现有产品也很协调。", "键盘交互和细节都有照顾到，团队可以专注业务。"] : ["The components match our designs and cut delivery time in half.", "The motion feels natural and fits our existing product.", "Keyboard interactions and small details let our team focus on the product."];
  useEffect(() => {
    if (!auto || hover || focused || reduced || motion === "none") return;
    const timer = setTimeout(() => setIndex(value => (value + 1) % names.length), 5200);
    return () => clearTimeout(timer);
  }, [auto, hover, focused, reduced, motion, index, names.length]);
  return <div className="flex w-full flex-col gap-4" onPointerEnter={() => setHover(true)} onPointerLeave={() => setHover(false)} onFocusCapture={() => setFocused(true)} onBlurCapture={event => { if (!event.currentTarget.contains(event.relatedTarget)) setFocused(false); }}>
    <AnimatePresence mode="wait" initial={false}><m.div key={index} initial={{ opacity: 0, x: reduced || motion === "none" ? 0 : 16 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: reduced || motion === "none" ? 0 : -16 }} transition={{ duration: reduced || motion === "none" ? 0 : .25 }}>
      <ReviewItem variant="card" width="full" avatar={portraits[index]} name={names[index]} date={zh ? "团队评价" : "Team review"} rating={5} content={quotes[index]} />
    </m.div></AnimatePresence>
    <div className="flex flex-wrap items-center gap-3">
      <IconButton motion={motion} size="sm" color={color} variant="ghost" aria-label={zh ? "上一条评价" : "Previous review"} onClick={() => setIndex((index + names.length - 1) % names.length)}><AltArrowLeftLinear size={18} /></IconButton>
      {names.map((name, i) => <button key={name} type="button" aria-label={zh ? `查看${name}的评价` : `Review by ${name}`} aria-pressed={index === i} onClick={() => setIndex(i)} className="rounded-full p-1 outline-offset-2 focus-visible:outline-2" style={{ outline: index === i ? `2px solid ${accent(color)}` : undefined }}><Avatar src={portraits[i]} alt={name} size="sm" /></button>)}
      <IconButton motion={motion} size="sm" color={color} variant="ghost" aria-label={zh ? "下一条评价" : "Next review"} onClick={() => setIndex((index + 1) % names.length)}><AltArrowRightLinear size={18} /></IconButton>
      <Button motion={motion} size="sm" color="black" variant="tertiary" aria-pressed={auto} onClick={() => setAuto(!auto)}>{auto ? (zh ? "暂停轮播" : "Pause") : (zh ? "自动轮播" : "Play")}</Button>
      <span className="text-xs text-fg-grey-500" role="status">{index + 1} / {names.length}</span>
    </div>
  </div>;
}

export function EventRegistrationExample({ locale, color, motion }: FusionSettings) {
  const zh = locale === "zh";
  const [rsvp, setRsvp] = useState(0);
  const [calendar, setCalendar] = useState(false);
  const labels = zh ? ["参加", "待定", "不参加"] : ["Going", "Maybe", "Not going"];
  return <SurfaceCard title={zh ? "动效设计交流夜" : "Motion design evening"}>
    <div className="flex flex-col gap-4">
      <EventCard width="full" title={zh ? "一起拆解一个自然的交互" : "Explore one natural interaction together"} timeRange={zh ? "10 月 24 日 · 19:30–21:00" : "24 Oct · 19:30–21:00"} color={color} avatars={portraits} overflowCount={34 + (rsvp === 0 ? 1 : 0)} />
      <p className="text-sm leading-6 text-fg-grey-700">{zh ? "带上电脑，现场交流设计和实现方法。" : "Bring a laptop and share design and implementation ideas."}</p>
      <div className="flex flex-wrap items-center gap-3"><ButtonGroup items={labels.map(label => ({ label }))} activeIndex={rsvp} onChange={setRsvp} color={color} motion={motion} ariaLabel={zh ? "参加意向" : "RSVP"} /><Button motion={motion} size="sm" color={color} variant="tertiary" aria-pressed={calendar} iconLeft={<CalendarLinear size={16} />} onClick={() => setCalendar(!calendar)}>{calendar ? (zh ? "已加入日程" : "Added to schedule") : (zh ? "加入日程" : "Add to schedule")}</Button></div>
      <p role="status" className="text-xs text-fg-grey-700">{zh ? `剩余 ${rsvp === 0 ? 12 : 13} / 50 个名额 · ${labels[rsvp]}` : `${rsvp === 0 ? 12 : 13} / 50 spots left · ${labels[rsvp]}`}</p>
    </div>
  </SurfaceCard>;
}

export function TimeZoneExample({ locale, color }: FusionSettings) {
  const zh = locale === "zh";
  const [hour, setHour] = useState(10);
  const [day, setDay] = useState("2026-10-14");
  const zones = [[zh ? "上海" : "Shanghai", "Asia/Shanghai"], [zh ? "伦敦" : "London", "Europe/London"], [zh ? "纽约" : "New York", "America/New_York"]];
  const date = new Date(`${day || "2026-10-14"}T${String(hour).padStart(2, "0")}:00:00Z`);
  const times = zones.map(([name, zone]) => {
    const localHour = Number(new Intl.DateTimeFormat("en-GB", { timeZone: zone, hour: "2-digit", hourCycle: "h23" }).format(date));
    return { name, localHour, available: localHour >= 9 && localHour < 18, display: new Intl.DateTimeFormat(zh ? "zh-CN" : "en-GB", { timeZone: zone, month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", hourCycle: "h23" }).format(date) };
  });
  return <SurfaceCard title={zh ? "查找共同工作时间" : "Find shared working hours"}>
    <div className="flex flex-col gap-5">
      <Datepicker label={zh ? "日期" : "Date"} locale={locale} value={new Date(`${day}T12:00:00`)} color={color} onChange={value => setDay(`${value.getFullYear()}-${String(value.getMonth() + 1).padStart(2, "0")}-${String(value.getDate()).padStart(2, "0")}`)} />
      <label className="flex flex-col gap-2 text-sm text-fg-grey-700">UTC {String(hour).padStart(2, "0")}:00<input type="range" min={0} max={23} step={1} value={hour} aria-label={zh ? "UTC 小时" : "UTC hour"} onChange={event => setHour(Number(event.target.value))} style={{ accentColor: accent(color) }} /></label>
      {times.map(time => <div key={time.name} className="flex flex-col gap-2"><div className="flex flex-wrap justify-between gap-2 text-sm"><span className="font-medium text-fg-black">{time.name}</span><span className="text-fg-grey-700">{time.display} · {time.available ? (zh ? "工作时间" : "Working") : (zh ? "非工作时间" : "Off hours")}</span></div><div className="relative h-3 overflow-hidden rounded-full bg-fg-grey-100"><span className="absolute inset-y-0 left-[37.5%] w-[37.5%] bg-fg-grey-300" /><span className="absolute inset-y-0 w-1 rounded-full" style={{ left: `${time.localHour / 24 * 100}%`, background: accent(color) }} /></div></div>)}
      <p role="status" className="text-sm font-medium text-fg-grey-900">{zh ? "当前处于工作时间的城市" : "Cities in working hours"}：{times.filter(time => time.available).length} / 3</p>
    </div>
  </SurfaceCard>;
}

export function ScheduleConflictExample({ locale, color, motion }: FusionSettings) {
  const zh = locale === "zh";
  const [resolved, setResolved] = useState(false);
  const reduced = useReducedMotion();
  return <SurfaceCard title={zh ? "安排团队日程" : "Plan team meetings"}>
    <div className="flex flex-col gap-4">
      <div className="flex justify-between text-xs text-fg-grey-500"><span>14:00</span><span>15:00</span><span>16:00</span></div>
      <div className="relative h-36 rounded-xl border border-fg-grey-200 bg-fg-grey-50 p-3">
        <div className="w-1/2 pr-1"><EventTag label={zh ? "团队评审 · 14:00–15:00" : "Team review · 14:00–15:00"} color={color} block /></div>
        <m.div className="absolute top-20 w-1/2 pr-3" animate={{ left: resolved ? "50%" : "25%" }} transition={{ duration: reduced || motion === "none" ? 0 : .35 }}><EventTag label={zh ? "一对一沟通" : "1:1 meeting"} color={resolved ? color : "red"} block /></m.div>
      </div>
      <p role="status" className={resolved ? "text-sm text-fg-grey-700" : "text-sm text-fg-red"}>{resolved ? (zh ? "15:00–16:00，冲突已解决" : "15:00–16:00, conflict resolved") : (zh ? "14:30–15:30，重叠 30 分钟" : "14:30–15:30, 30 minute overlap")}</p>
      <Button motion={motion} size="sm" color={color} variant={resolved ? "tertiary" : "primary"} aria-pressed={resolved} onClick={() => setResolved(!resolved)}>{resolved ? (zh ? "撤销调整" : "Undo change") : (zh ? "移至 15:00" : "Move to 15:00")}</Button>
    </div>
  </SurfaceCard>;
}

export function ApprovalWorkflowExample({ locale, color, motion }: FusionSettings) {
  const zh = locale === "zh";
  const [stage, setStage] = useState(1);
  const reduced = useReducedMotion();
  const names = zh ? ["林晓", "陈凡", "周宁"] : ["Alex Lin", "Chris Chen", "Jamie Zhou"];
  const roles = zh ? ["起草", "复核", "批准"] : ["Draft", "Review", "Approve"];
  return <SurfaceCard title={zh ? "品牌方案审批" : "Brand draft approval"}>
    <div className="flex flex-col gap-5">
      <div className="flex flex-wrap items-center gap-3">{names.map((name, i) => <div key={name} className="flex items-center gap-3"><div className="flex flex-col items-center gap-2"><Avatar src={portraits[i]} alt={name} /><span className="text-sm font-medium">{name}</span><span className="text-xs text-fg-grey-700">{roles[i]}</span><m.span animate={{ opacity: i < stage ? 1 : .25, scale: i < stage ? 1 : .85 }} transition={{ duration: reduced || motion === "none" ? 0 : .2 }}><CheckCircleLinear size={20} color={i < stage ? accent(color) : "var(--fg-grey-400)"} /></m.span></div>{i < 2 && <AltArrowRightLinear size={18} color="var(--fg-grey-500)" />}</div>)}</div>
      <p role="status" className="text-sm text-fg-grey-700">{stage === 3 ? (zh ? "审批完成" : "Approved") : (zh ? `等待${names[stage]}${roles[stage]}` : `Waiting for ${names[stage]} to ${roles[stage].toLowerCase()}`)}</p>
      <Button motion={motion} size="sm" color={color} onClick={() => setStage(stage === 3 ? 1 : stage + 1)}>{stage === 1 ? (zh ? "通过复核" : "Approve review") : stage === 2 ? (zh ? "最终批准" : "Final approval") : (zh ? "重置流程" : "Reset workflow")}</Button>
    </div>
  </SurfaceCard>;
}

export function WorkAssignmentExample({ locale, color, motion }: FusionSettings) {
  const zh = locale === "zh";
  const [loads, setLoads] = useState([2, 1, 3]);
  const [task, setTask] = useState(0);
  const [last, setLast] = useState<{ member: number; job: string } | null>(null);
  const names = zh ? ["林晓", "陈凡", "周宁"] : ["Alex Lin", "Chris Chen", "Jamie Zhou"];
  const jobs = zh ? ["首页无障碍检查", "整理品牌规范", "检查移动端菜单", "统一图标样式", "补充表单校验", "检查日历交互", "完善空态文案", "复核图表单位", "检查键盘导航"] : ["Homepage accessibility", "Tidy the brand guide", "Review the mobile menu", "Align the icon set", "Add form validation", "Review calendar interactions", "Improve empty-state copy", "Verify chart units", "Check keyboard navigation"];
  const exhausted = loads.every(load => load >= 5);
  return <div className="flex w-full flex-col gap-4">
    <div className="flex flex-col gap-2"><p className="text-sm font-medium">{zh ? `已分派 ${task} / ${jobs.length} 项任务` : `${task} / ${jobs.length} tasks assigned`}</p><ProgressBar value={task / jobs.length * 100} color={color} motion={motion} label={zh ? "总分派进度" : "Overall assignment progress"} /></div>
    <SurfaceCard title={exhausted ? (zh ? "全部任务已分派" : "All tasks assigned") : jobs[task]}><p className="text-sm text-fg-grey-700">{exhausted ? (zh ? "成员容量已满，可重置后重新体验。" : "Members are at capacity. Reset to try again.") : (zh ? "待分派任务：选择有剩余容量的成员" : "Next task: choose a member with available capacity")}</p></SurfaceCard>
    {names.map((name, i) => <SurfaceCard key={name} padding="sm"><div className="flex items-center gap-3"><Avatar src={portraits[i]} alt={name} size="sm" /><span className="min-w-0 flex-1 text-sm font-medium">{name}</span><span className="text-xs text-fg-grey-700">{loads[i]} / 5</span><Button motion={motion} size="sm" variant="secondary" color={color} disabled={loads[i] >= 5} onClick={() => { setLoads(current => current.map((load, j) => i === j ? load + 1 : load)); setTask(task + 1); setLast({ member: i, job: jobs[task] }); }}>{zh ? "分派" : "Assign"}</Button></div><div className="mt-3"><ProgressBar value={loads[i] / 5 * 100} color={color} /></div></SurfaceCard>)}
    <p role="status" className="text-xs text-fg-grey-700">{last === null ? (zh ? "尚未分派新任务" : "No new assignments") : (zh ? `已将“${last.job}”分派给${names[last.member]}` : `Assigned “${last.job}” to ${names[last.member]}`)}</p>
    <Button motion={motion} size="sm" color="black" variant="tertiary" onClick={() => { setLoads([2, 1, 3]); setTask(0); setLast(null); }}>{zh ? "重置任务" : "Reset assignments"}</Button>
  </div>;
}

type PermissionRow = { id: string; name: string; permissions: boolean[]; locked?: boolean };
export function PermissionMatrixExample({ locale, color, motion }: FusionSettings) {
  const zh = locale === "zh";
  const [permissions, setPermissions] = useState([[true, true, true], [true, false, false], [true, false, false]]);
  const names = zh ? ["所有者", "编辑者", "访客"] : ["Owner", "Editor", "Guest"];
  const actions = zh ? ["查看", "编辑", "分享"] : ["View", "Edit", "Share"];
  const rows = names.map((name, i) => ({ id: String(i), name, permissions: permissions[i], locked: i === 0 }));
  const columns: ColumnDef<PermissionRow>[] = [{ key: "role", header: zh ? "角色" : "Role", render: row => row.name }, ...actions.map((label, action) => ({ key: String(action), header: label, render: (row: PermissionRow) => <Checkbox checked={row.permissions[action]} disabled={row.locked} color={color} motion={motion} aria-label={`${row.name} · ${label}`} onChange={checked => setPermissions(current => current.map((list, index) => index === Number(row.id) ? list.map((value, i) => i === action ? checked : value) : list))} /> }))];
  return <div className="w-full min-w-0"><DataTable title={zh ? "角色权限" : "Role permissions"} subtitle={zh ? "所有者保留全部权限" : "Owners retain all permissions"} columns={columns} rows={rows} color={color} showCheckbox={false} showPagination={false} getRowKey={row => row.id} tableMinWidth={360} /></div>;
}

export function CollaborationExample({ locale, color, motion }: FusionSettings) {
  const zh = locale === "zh";
  const people = ["design", "research", "engineering"].map((id, i) => ({ id, name: (zh ? ["设计智能体", "研究智能体", "工程智能体"] : ["Design agent", "Research agent", "Engineering agent"])[i], role: (zh ? ["交互设计", "资料研究", "组件实现"] : ["Design", "Research", "Implementation"])[i], avatar: portraits[i] }));
  const [ids, setIds] = useState(["design", "research"]);
  const [active, setActive] = useState("design");
  const [picked, setPicked] = useState<string[]>([]);
  const reduced = useReducedMotion();
  function remove(id: string) { const next = ids.filter(item => item !== id); setIds(next); if (active === id) setActive(next[0] ?? ""); }
  return <div className="flex w-full flex-col gap-4">
    <div className="flex flex-wrap items-center justify-between gap-3"><span className="text-sm font-semibold">{zh ? "协作成员" : "Collaborators"}</span><AvatarGroup>{people.filter(person => ids.includes(person.id)).map(person => <Avatar key={person.id} src={person.avatar} alt={person.name} size="sm" />)}</AvatarGroup></div>
    <div className="flex flex-wrap gap-3"><AnimatePresence initial={false}>{people.filter(person => ids.includes(person.id)).map(person => <m.div layout key={person.id} className="relative rounded-2xl border p-3" style={{ borderColor: active === person.id ? accent(color) : "var(--fg-grey-200)" }} initial={{ opacity: 0, scale: .85 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: .85 }} transition={{ duration: reduced || motion === "none" ? 0 : .25 }}>
      <button type="button" className="flex min-w-24 flex-col items-center gap-2 rounded-lg px-3 pb-1 pt-4 focus-visible:outline-2 focus-visible:outline-accent" aria-pressed={active === person.id} onClick={() => setActive(person.id)}><Avatar src={person.avatar} alt={person.name} /><span className="text-sm font-medium">{person.name}</span><span className="text-xs text-fg-grey-700">{active === person.id ? (zh ? "当前负责" : "Lead") : person.role}</span></button>
      <div className="absolute right-1 top-1"><IconButton motion={motion} size="sm" variant="ghost" color="black" aria-label={`${zh ? "移除" : "Remove"} ${person.name}`} onClick={() => remove(person.id)}><CloseCircleLinear size={16} /></IconButton></div>
    </m.div>)}</AnimatePresence></div>
    <AddMember accent={color} members={people.filter(person => !ids.includes(person.id))} selectedIds={picked} onSelectionChange={setPicked} onAdd={next => { setIds(current => [...current, ...next]); if (!active) setActive(next[0] ?? ""); }} motion={motion} labels={zh ? undefined : { title: "Add collaborators", search: "Search members", empty: "All members added", add: "Add to team", adding: "Adding…", added: "Added", error: "Failed. Retry", select: "Select", remove: "Remove", selected: "Selected", viewAll: "View all", previous: "Previous", next: "Next" }} />
    <p role="status" className="text-xs text-fg-grey-700">{active ? `${zh ? "当前负责人" : "Current lead"}：${people.find(person => person.id === active)?.name}` : (zh ? "添加成员后选择负责人" : "Add a member to choose a lead")}</p>
  </div>;
}

"use client";

import type { FusionExampleProps } from "./types";
import { CodeFoldingExample, DiffReviewExample, FindReplaceExample, MarkdownExample, TextAssemblyExample, UndoHistoryExample, VersionHistoryExample } from "./composition-editing";
import { ApprovalWorkflowExample, CollaborationExample, EventRegistrationExample, PermissionMatrixExample, ReviewCarouselExample, ScheduleConflictExample, TimeZoneExample, WorkAssignmentExample } from "./composition-workflow";
import { GeneratedReviewExample, SearchRecoveryExample } from "./composition-recovery";

export const compositionIds = ["057", "059", "092", "108", "110", "126", "127", "128", "129", "176", "177", "179", "180", "181", "184", "F04", "F05", "F06"] as const;
const examples = {
  "057": ReviewCarouselExample, "059": EventRegistrationExample, "108": TimeZoneExample,
  "110": ScheduleConflictExample, "126": MarkdownExample, "127": DiffReviewExample,
  "128": FindReplaceExample, "129": CodeFoldingExample, "176": VersionHistoryExample,
  "177": UndoHistoryExample, "179": TextAssemblyExample, "180": ApprovalWorkflowExample,
  "181": WorkAssignmentExample, "184": PermissionMatrixExample, F04: GeneratedReviewExample,
  F05: CollaborationExample,
};
export function CompositionExamples(props: FusionExampleProps) {
  if (props.id === "092" || props.id === "F06") return <SearchRecoveryExample key={`${props.id}-${props.locale}`} {...props} />;
  const Example = examples[props.id as keyof typeof examples];
  return Example ? <Example key={`${props.id}-${props.locale}`} {...props} /> : null;
}

